import {demand} from './operations.js';
import {completedQuantity,overdueDays} from './manufacturing.js';
import {STATUSES} from './model.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function shopBoard(parts,dateLabel,{isAdmin=false}={}){
 return `<div class="shop-board">${STATUSES.map((stage,index)=>{
 const rows=parts.filter(p=>p.status===stage).sort((a,b)=>Number(b.blocked)-Number(a.blocked)||(a.due||'9999').localeCompare(b.due||'9999'));
 const next=STATUSES[index+1];
 return `<section class="shop-lane lane-${index}"><h3><span>${stage}</span><span class="lane-count">${rows.length}</span></h3><div class="shop-lane-cards">${rows.map(p=>`<article class="shop-card ${p.blocked?'is-blocked':''} ${overdueDays(p)?'is-overdue':''}"><div class="card-top"><span class="part-number">${esc(p.number||'No number')}</span>${isAdmin?`<details class="card-menu"><summary aria-label="Stage actions for ${esc(p.name)}">···</summary><label>Move to<select data-status="${esc(p.id)}" aria-label="Stage for ${esc(p.name)}">${STATUSES.map(s=>`<option ${s===stage?'selected':''}>${s}</option>`).join('')}</select></label></details>`:''}</div><button class="part-name" data-edit="${esc(p.id)}">${esc(p.name)}</button><div class="card-tags">${p.blocked?'<span class="blocked-tag">Blocked</span>':''}${overdueDays(p)?'<span class="overdue-badge">Overdue</span>':''}</div><div class="card-assignment"><span>${esc(p.assignedTo||p.owner||'Unassigned')}</span><span>Qty ${p.quantity}</span></div><p class="card-process">${esc(p.subsystem||'No subsystem')} · ${esc(p.material||'No material')}</p>${p.due?`<p class="card-due ${overdueDays(p)?'due-overdue':''}">Due ${esc(dateLabel(p.due))}</p>`:''}${p.blocked?`<p class="shop-note">${esc(p.blockReason||'Blocked')}<br>${esc(p.blockOwner||'Resolver needed')} · ${esc(p.blockNext||'Next action needed')}</p>`:''}<div class="batch-progress"><span>${completedQuantity(p)} / ${demand(p)} parts made</span><progress max="${demand(p)}" value="${completedQuantity(p)}" aria-label="Parts made for ${esc(p.name)}"></progress></div>${isAdmin&&next?`<div class="card-actions"><button class="shop-action" data-advance="${esc(p.id)}" data-next="${next}">${next==='Done'?'Mark Done':'Move to '+next}</button><button class="block-toggle" data-block="${esc(p.id)}">${p.blocked?'Unblock':'Block'}</button></div>`:''}</article>`).join('')||'<p class="lane-empty">No parts</p>'}</div></section>`;
 }).join('')}</div>`;
}
